import random
import re
import time

from typing import List, Union, Optional
from contextlib import suppress

from taf.nms.netact.cm_editor.api.exceptions import ManagedObjectNotFound
from taf.ul.alarms_watchdog import Alarm

from taf.rfrl.csv4all.resources.node.feature.netact.exceptions import VerifyCellsNetactError, SoftwareStatusError
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator
from taf.rfrl.csv4all.resources.utilities.exceptions import FunctionTimeoutException
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger, wait_until_success, time_limit
from taf.rfrl.csv4all.resources.node.feature.utilities.feature_node import FeatureNode


class NetactNode(FeatureNode):
    cell_lock_template = f"{__file__.rsplit('/', 1)[0]}/test_data_files/CELL_LOCK_TEST_TEMPLATE.xml"
    cell_lock_file = f"{__file__.rsplit('/', 1)[0]}/test_data_files/CELL_LOCK_TEST.xml"
    cell_unlock_file = f"{__file__.rsplit('/', 1)[0]}/test_data_files/CELL_UNLOCK_TEST.xml"

    def __init__(self, node_mrbts_id: str, source_sw: str, target_sw: str,
                 node_alias: Optional[str] = None, node_vm: Union[str, dict] = None,
                 secondary_vm: Union[str, dict] = None, bts_host_ip: Optional[str] = "192.168.255.129",
                 external_dcap_host: Optional[str] = None, dcap_port: Optional[str] = "9443",
                 dcap_custom_profiles: Optional[dict] = None, hw_to_onair_timeout: Optional[int] = 900,
                 alarm_timer: Optional[int] = 60, custom_allowed_alarms: Optional[list] = None,
                 temporary_allowed_alarms: Optional[list] = None, critical_alarms: List[Union[str, Alarm]] = None,
                 pdu_config: Optional[list] = None,
                 logs_dir: Optional[str] = None, testline_scout_name: Optional[str] = None,
                 use_dcap: Optional[bool] = False, verify_syslog: Optional[bool] = True,
                 syslog_ignored_prints: Union[list, str] = None, user_syslog_suspicious_prints: Union[list, str] = None,
                 webem_username: str = 'Nemuadmin', webem_password: str = 'nemuuser',
                 node_ssh_username: str = "toor4nsn", node_ssh_password: str = "oZPS0POrRieRtu",
                 check_mplane: bool = True, oran_files: dict = None, airphone_details: dict = None,
                 check_amf: bool = True, admin_setup_timeout: int = 120, setup_energy_saving: bool = False,
                 ru_manager_yaml_file: Union[str, None] = None, **kwargs):
        super().__init__(node_mrbts_id, node_alias, node_vm, secondary_vm, bts_host_ip, external_dcap_host, dcap_port,
                         dcap_custom_profiles, hw_to_onair_timeout, alarm_timer, source_sw, target_sw,
                         custom_allowed_alarms, temporary_allowed_alarms, critical_alarms, pdu_config,
                         logs_dir, testline_scout_name, use_dcap, verify_syslog, syslog_ignored_prints,
                         user_syslog_suspicious_prints, webem_username, webem_password, node_ssh_username,
                         node_ssh_password, check_mplane, oran_files, airphone_details, check_amf, admin_setup_timeout,
                         setup_energy_saving, ru_manager_yaml_file, **kwargs)
        self.netact_target_sw = None
        self.cell_to_lock = None
        self.netboot_changed = None
        self.btsl_side = None
        self.mo_dist_name = f"PLMN-PLMN/MRBTS-{node_mrbts_id}"
        self.netact = None
        self.mo_release = None
        self.current_iteration_target_sw = None
        self.passive_sw_before_test = None

    @method_decorator("node_alias")
    def setup_node(self) -> None:
        super().setup_node()
        self.cell_to_lock = self.get_cell_to_lock()
        self.btsl_side = self.get_btsl_side()
        self.mo_release = self.get_mo_release(self.get_active_sw_for_netact())

    @staticmethod
    def get_mo_release(sw_name):
        sw_name_splitted = sw_name.split("_")
        if sw_name_splitted[1] == "FSM3" and sw_name_splitted[0] != "SBTS23R1":
            return f"{sw_name_splitted[0]}FSM3"
        return sw_name_splitted[0]

    @method_decorator("node_alias")
    def set_node_mplane(self):
        self.scf.load_scf(file_path=self.scf_file)
        mplane_version = "mPlaneIpv4AddressDN" if self.netact.ip_version == "IPv4" else "mPlaneIpv6AddressDN"
        mplane_distname = self.scf.get_all_values_from_scf_by_pattern(p_name=mplane_version)
        try:
            return self.scf.get_all_values_from_scf_by_pattern(dist_name=mplane_distname[0] + ".*",
                                                               p_name="localIpAddrAllocated")[0]
        except IndexError:
            test_logger(f"[{self.node_alias}] There is no mplane {self.netact.ip_version} configured in scf", "ERROR")
            raise

    @method_decorator("node_alias")
    def update_sw_and_wait_for_reload(self, timeout: int = 300):
        self.download_sw()
        time.sleep(5)
        self.activate_sw(timeout=timeout)

    @method_decorator("node_alias")
    def update_sw(self) -> None:
        if self.oran_files and 'upgrade' in self.oran_files:
            self.update_ofegsa_sw(self.oran_files['upgrade'])
        test_logger(f"[{self.node_alias}] Starting SW Provision")
        self.netact.provision_sw(self.netact_target_sw, self.mo_dist_name)
        test_logger(f"[{self.node_alias}] Sw Provision request completed waiting for SW activation.")

    @method_decorator("node_alias")
    def download_sw(self) -> None:
        if self.oran_files and 'upgrade' in self.oran_files:
            self.update_ofegsa_sw(self.oran_files['upgrade'])
        test_logger(f"[{self.node_alias}] Starting SW Download")
        self.netact.download_sw(target_sw=self.netact_target_sw, mo_dist_name=self.mo_dist_name)
        test_logger(f"[{self.node_alias}] Sw Download request completed.")

    @method_decorator("node_alias")
    def activate_sw(self, path: str = None, timeout: int = 300) -> None:
        test_logger(f"[{self.node_alias}] Starting SW Activation")
        self.netact.activate_sw(target_sw=self.netact_target_sw, mo_dist_name=self.mo_dist_name)
        time.sleep(3)
        if path:
            self.admin.collect_infomodel_log_from_current_session(f"{path}/oam_kpis/{self.node_alias}/update/"
                                                                  f"OAM_KPI_{self.node_alias}_1.ims2")
        test_logger(f"[{self.node_alias}] Sw Update request completed waiting for SW activation.")
        if self.netact_target_sw.split("_", 3)[2] == "9999" or self.netact_target_sw.split("_", 3)[2] == "9990":
            expected_active_sw = "_".join(["SBTS00", self.netact_target_sw.split("_", 1)[1]])
        else:
            expected_active_sw = self.netact_target_sw
        self.wait_until_new_sw_activated(expected_active_sw, timeout)
        test_logger(f"[{self.node_alias}] {self.netact_target_sw} is activated")

    @method_decorator("node_alias")
    def perform_rollback(self) -> None:
        if self.oran_files and 'rollback' in self.oran_files:
            self.update_ofegsa_sw(self.oran_files['rollback'])
        test_logger(f"Starting SW Rollback on {self.mrbts_id}")
        self.netact.rollback_sw(self.mo_dist_name)

    @method_decorator("node_alias")
    def integrate_parallel_mrbts(self):
        test_logger(f"Integrating {self.mrbts_id} with Netact")
        self.netact.integrate_mrbts_with_netact(self.mo_dist_name, self.mplane, self.mo_release)

    @method_decorator("node_alias")
    def integrate_mrbts(self):
        test_logger(f"Integrating {self.mrbts_id} with Netact")
        with time_limit(1800):
            self.netact.integrate_mrbts_with_netact(self.mo_dist_name, self.mplane, self.mo_release)

    @method_decorator("node_alias")
    def deintegrate_mrbts(self):
        test_logger(f"Deintegrating {self.mrbts_id} from Netact")
        return self.netact.deintegrate_mrbts_from_netact(self.mo_dist_name)

    @method_decorator("node_alias")
    def check_connection_to_netact(self) -> None:
        try:
            test_logger(f"[{self.node_alias}] Checking connection status with Netact")
            wait_until_success(600, 10, self.netact.cm_upload, self.mo_dist_name)
            test_logger(f"{self.mrbts_id} is connected to Netact")
        except Exception as e:
            test_logger(f"[{self.node_alias}] Checking connection status with Netact failed")
            test_logger(e, "DEBUG")
            raise

    @method_decorator("node_alias")
    def get_active_sw_for_netact(self) -> str:
        return self.admin.get_software_info(timeout=300)["Active SW version"]

    @method_decorator("node_alias")
    def get_cell_to_lock(self) -> Union[str, None]:
        mapped_cells = []
        for smod in self.systemModules:
            mapped_cells += self.systemModules[smod].get("Mapped Cells")
        if mapped_cells:
            mapped_cells = [cell for cell in mapped_cells for rat in self.cells_per_rat
                            if cell in self.cells_per_rat[rat] and not self.cells_per_rat[rat][cell].get("IoT Cell")
                            and not any(sub in cell.split('/')[-1] for sub in ['WNCEL', 'GNCEL'])]
            if mapped_cells:
                return random.choice(mapped_cells)
        test_logger(f"[{self.node_alias}] Cell to lock is not assigned, cm provision can't be tested", "ERROR")
        return None

    @method_decorator("node_alias")
    def cm_provision(self) -> None:
        try:
            if not self.cell_to_lock:
                return
            test_logger(f"[{self.node_alias}] CM Provision cell: {self.cell_to_lock}")
            enb_id = self.mrbts_id.replace('MRBTS-', '')
            self.create_cell_lock_unlock_plans()
            with suppress(Exception):
                self.netact.delete_plan(plan_name=f"CELL_LOCK_TEST_NEW_{enb_id}")
            with suppress(Exception):
                self.netact.delete_plan(plan_name=f"CELL_UNLOCK_TEST_NEW_{enb_id}")
            test_data_files = f"{__file__.rsplit('/', 1)[0]}/test_data_files/"
            self.netact.import_configuration(local_dir=test_data_files, file_name="CELL_LOCK_TEST.xml",
                                             plan_name=f"CELL_LOCK_TEST_NEW_{enb_id}")
            self.netact.import_configuration(local_dir=test_data_files, file_name="CELL_UNLOCK_TEST.xml",
                                             plan_name=f"CELL_UNLOCK_TEST_NEW_{enb_id}")
            self.plan_provision(f"CELL_LOCK_TEST_NEW_{enb_id}")
            correct_status = self.check_correct_status_after_cell_lock()
            self.plan_provision(f"CELL_UNLOCK_TEST_NEW_{enb_id}")
            if correct_status:
                test_logger(f"[{self.node_alias}] CM PROVISION PASSED", hyperlink=True)
            else:
                test_logger(f"{self.cell_to_lock} lock failed", "ERROR")
                test_logger(f"[{self.node_alias}] CM PROVISION FAILED", "ERROR")
        except Exception as e:
            test_logger(f"[{self.node_alias}] CM PROVISION FAILED", "ERROR")
            self.btsverify.bts_fault_message += f"\nCM Provision Failed: \n{e}"
            test_logger(e, console=False)
            raise

    @method_decorator("node_alias")
    def plan_provision(self, plan_name: str) -> None:
        self.netact.provision_plan(plan_name=plan_name)

    @method_decorator("node_alias")
    def check_correct_status_after_cell_lock(self) -> bool:
        cell_name = self.cell_to_lock.split("/")[-1].replace('-', '_R-')
        cell_class_name = "LNCEL" if "LNCEL" in self.cell_to_lock.split("/")[-1] else "NRCEL"

        def verify_cell_lock_state():
            cell_list = self.admin.get_parameters_for_all(class_name=cell_class_name)
            for cell in cell_list:
                if cell_name not in cell["id"]:
                    continue
                if cell['administrativeState'] in ("Locked", "locked"):
                    return True
            raise VerifyCellsNetactError("Verification of cell lock failed")
        try:
            wait_until_success(300, 10, verify_cell_lock_state)
            return True
        except FunctionTimeoutException as timeout:
            test_logger(timeout, "ERROR")
            return False

    @method_decorator("node_alias")
    def create_cell_lock_unlock_plans(self) -> None:
        release = self.get_mo_release(self.get_active_sw_for_netact())
        enb_id = self.mrbts_id.replace("MRBTS-", "")
        nr_lock = "3" if "LNCEL" in self.cell_to_lock.split("/")[-1] else "0"
        nr_unlock = "1" if "LNCEL" in self.cell_to_lock.split("/")[-1] else "2"
        class_cell = "LNCEL" if "LNCEL" in self.cell_to_lock.split("/")[-1] else "NRCELL"
        with open(self.__class__.cell_lock_template, "r") as template:
            with open(self.__class__.cell_lock_file, "w") as cell_lock, \
                    open(self.__class__.cell_unlock_file, "w") as cell_unlock:
                template = template.read()
                replaced = template.replace("%ENB_RELEASE%", release).replace("%ENB_ID%", enb_id) \
                    .replace("%CLASS_CELL%", class_cell).replace("%CELL_DISTNAME%", self.cell_to_lock)
                final_lock_template = replaced.replace("%nr_lock%", nr_lock)
                test_logger(f"Lock Template: {final_lock_template}", "DEBUG")
                cell_lock.write(final_lock_template)
                final_unlock_template = replaced.replace("%nr_lock%", nr_unlock)
                test_logger(f"Unlock Template: {final_unlock_template}", "DEBUG")
                cell_unlock.write(final_unlock_template)

    @method_decorator('mrbts_id')
    def verify_node_after_fallback(self):
        self.wait_on_fallback_fault()
        self.verify_download_sw_from_netact()
        self.verify_node_bts_state()

    @method_decorator('mrbts_id')
    def verify_download_sw_from_netact(self):
        wait_until_success(600, 30, self.wait_on_all_modules)
        for _ in range(3):
            verification_with_errors = self.btsverify.verify_bts_state(return_error=True)
            if verification_with_errors:
                if self.verify_if_fault_exists("23"):
                    self.check_connection_to_netact()
                    self.wait_on_sw_download_start()
                    test_logger(f"[{self.node_alias}] Sw download from Netact is ongoing")
                    self.wait_on_sw_download_finish()
                else:
                    test_logger(f"[{self.node_alias}] FaultId: 23 doesnt exist")
                time.sleep(60)
            else:
                break

    @method_decorator("node_alias")
    def wait_on_fallback_fault(self):
        test_logger(f"[{self.node_alias}] Waiting on fallback fault")
        wait_until_success(1800, 60, self.verify_fallback_fault)
        test_logger(f"[{self.node_alias}] Fallback fault appeared")

    @method_decorator("node_alias")
    def wait_on_sw_download_start(self):
        test_logger(f"[{self.node_alias}] Waiting on sw download start")
        wait_until_success(3600, 5, self.verify_sw_download_start)

    @method_decorator("node_alias")
    def verify_sw_download_start(self):
        if self.verify_if_fault_exists("23") and self.get_download_status() != "Ongoing":
            raise SoftwareStatusError("Software download is not yet started")

    @method_decorator("node_alias")
    def wait_on_sw_download_finish(self):
        test_logger(f"[{self.node_alias}] Waiting on sw download finish")
        wait_until_success(14400, 60, self.verify_sw_download_finish)
        test_logger(f"[{self.node_alias}] All sw download operations from Netact are finished")

    @method_decorator("node_alias")
    def verify_sw_download_finish(self):
        if self.verify_if_fault_exists(["23", "10"]):
            raise SoftwareStatusError("Software download is not yet finished")

    @method_decorator("node_alias")
    def get_download_status(self):
        swm_info = self.admin.get_parameters(f"/MRBTS-1/RAT-1/SWM-{self.btsl_side}", pattern=".*")
        return swm_info.get("swDownloadInfo").get("state")

    @method_decorator("node_alias")
    def get_btsl_side(self):
        internal_id = [self.systemModules[smod].get("Internal Id") for smod in self.systemModules][0]
        bts_l_side_match = re.search(r"RUNTIME_VIEW-[1-4]", internal_id)
        return bts_l_side_match.group(0).split("-")[-1] if bts_l_side_match else "1"

    @method_decorator("node_alias")
    def reset_ne(self, bts_reset_type: str, graceful_cell_shutdown: str = 'true'):
        test_logger(f"[{self.node_alias}] Starting site reset via NetAct")
        parameters = {'btsResetType': bts_reset_type,
                      'gracefulCellShutdown': graceful_cell_shutdown.lower()}
        self.netact.reset_ne(dist_names=self.mo_dist_name, parameters=parameters)

    @method_decorator("node_alias")
    def get_actual_config(self):
        return self.netact.get_actual_config()

    @method_decorator("node_alias")
    def get_managed_object(self, configuration, mo_id: str):
        return self.netact.get_managed_object(configuration, mo_id)

    @method_decorator("node_alias")
    def verify_cells_via_netact(self):
        self.btsverify.set_current_bts_info()
        actual_config = self.get_actual_config()
        all_cells = self.btsverify.cells_verifier.get_all_cells_state()
        results = self.get_cells_state_from_netact(all_cells, actual_config)
        test_logger(f"[{self.node_alias}] Checking cells via NetAct results: {results}", "DEBUG")
        faulty_entities = [cell for cell_id in results for cell, states in cell_id.items()
                           if any("Error" in state_value for state_value in states.values())]
        if faulty_entities:
            raise VerifyCellsNetactError(f"Cells with not the same state as from admin: {faulty_entities}")
        test_logger(f"[{self.node_alias}] Checking cells via NetAct passed")

    @method_decorator("node_alias")
    def get_cells_state_from_netact(self, dict_of_cells: dict, actual_config) -> list:
        results = []
        for cell_id, cell_statuses in dict_of_cells.items():
            if "GNCEL" in cell_id.split("/")[-1]:
                continue
            cell_admin_operationalstate = cell_statuses.get("operationalState").lower()
            try:
                cell_from_actual_config = self.get_managed_object(actual_config, mo_id=f"PLMN-PLMN/{cell_id}")
                state_from_actual_config = "enabled" if "1" in cell_from_actual_config.parameters["operationalState"] \
                    else "disabled"
            except ManagedObjectNotFound as e:
                test_logger(e, "ERROR")
                state_from_actual_config = "Object not found"
            results.append({
                cell_id: {"operationalState": f"State as expected {state_from_actual_config}"
                if cell_admin_operationalstate == state_from_actual_config else
                f"Error current value {state_from_actual_config} is different from admin cell state: "
                f"{cell_admin_operationalstate}"}})
        return results

    @method_decorator("node_alias")
    def clear_requested_ru_sw(self):
        if self.get_requested_ru_sw():
            self.add_temporary_alarm("23")

    @method_decorator("node_alias")
    def perform_cm_provision(self):
        self.cm_provision()
        self.verify_node_bts_state()

    @method_decorator("node_alias")
    def verify_cells_from_netact(self):
        try:
            wait_until_success(120, 20, self.verify_cells_via_netact)
        except Exception as e:
            test_logger(e, "ERROR")
            raise e

    @method_decorator("node_alias")
    def cleanup_after_fallback(self):
        if self.clear_fallback_fault():
            test_logger(f"[{self.node_alias}] FallbackCause file removed. Performing Reset Site.")
            self.reset_site()
            self.verify_node_bts_state()

    @method_decorator("node_alias")
    def postcondition_after_fallback(self):
        self.cleanup_after_fallback()
        if self.netboot_changed:
            self.change_netboot_state("on")

    @method_decorator("node_alias")
    def software_precheck(self, precheck_type: str = "fullCheck"):
        return self.netact.precheck_sw(self.netact_target_sw, self.mo_dist_name, precheck_type=precheck_type)

    def run_diagnostic_check(self):
        return self.netact.diagnostic_check(self.mo_dist_name)

    def save_diagnostic_report_to_file(self, logs_dir: str, report_data: str):
        if not report_data:
            test_logger("The diagnostic report data is empty, no CSV file will be created.", "WARN")
            return
        filename = f"{logs_dir}/{self.node_alias}_diagnostic_report.csv"
        try:
            with open(filename, 'w', encoding='utf-8') as csvfile:
                csvfile.write(report_data)
            test_logger(f"Diagnostic report successfully saved to {filename}", "DEBUG")
        except IOError as e:
            test_logger(f"Error writing to file {filename}: {e}", "DEBUG")
